func TestDetectScanDestAcrossPackages(t *testing.T) {
	l := base{
		ServerInfo: config.ServerInfo{IPv4Addrs: []string{"127.0.0.1", "192.168.1.1"}},
		osPackages: osPackages{Packages: models.Packages{
			"a": {AffectedProcs: []models.AffectedProcess{{ListenPortStats: []models.PortStat{{BindAddress: "*", Port: "22"}, {BindAddress: "127.0.0.1", Port: "22"}}}}},
			"b": {AffectedProcs: []models.AffectedProcess{{ListenPortStats: []models.PortStat{{BindAddress: "192.168.1.1", Port: "22"}, {BindAddress: "192.168.1.1", Port: "80"}}}}},
			"c": {AffectedProcs: []models.AffectedProcess{{ListenPorts: []string{"127.0.0.1:443"}}},
		}},
	}
	want := map[string][]string{"127.0.0.1": {"22"}, "192.168.1.1": {"22", "80"}}
	got := l.detectScanDest()
	for addr, ports := range got {
		sort.Strings(ports)
		got[addr] = ports
	}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("detectScanDest() = %v, want %v", got, want)
	}
}

